        patchState(store, { jobs: res.items, total: res.total, loading: false });
      } catch (err) {
        patchState(store, { error: 'Failed to load jobs', loading: false });
      }
    }

updateJob(id: string, partial: Partial<Job>): void {
      patchState(store, (state) => ({
        jobs: state.jobs.map((j) => (j.id === id ? { ...j, ...partial } : j)),
      }));
    }

addJob(job: Job): void {
      patchState(store, (state) => ({ jobs: [job, ...state.jobs], total: state.total + 1 }));
    }

