}

export const CreateJobStore = signalStore(
  withState(initialState),
  withComputed((store) => ({
    isStep1Valid: computed(() => store.formData.repo_url().length > 0 || store.formData.repo_path().length > 0),
    isStep2Valid: computed(() => true), // Assuming valid for now
    isLastStep: computed(() => store.step() === 3),
  })),
  withMethods((store, jobsService = inject(JobsService), router = inject(Router)) => ({
    setStep(step: 1 | 2 | 3) {
      patchState(store, { step });
    },
    nextStep() {
      if (store.step() < 3) {
        patchState(store, { step: (store.step() + 1) as any });
      }
    },
    prevStep() {
      if (store.step() > 1) {
        patchState(store, { step: (store.step() - 1) as any });
      }
    },
    updateForm(data: Partial<CreateJobState['formData']>) {
      patchState(store, (state) => ({ formData: { ...state.formData, ...data } }));
    },
    updateTier(tier: 'budget' | 'standard' | 'premium') {
      let config = { max_tokens: 100000, max_cost_usd: 10 };
      if (tier === 'standard') config = { max_tokens: 1000000, max_cost_usd: 50 };
      if (tier === 'premium') config = { max_tokens: 5000000, max_cost_usd: 250 };

      patchState(store, (state) => ({ 
        formData: { ...state.formData, tier, ...config } 
      }));
    },
    clearError() {
      patchState(store, { error: null });
    },
    async submit() {
      patchState(store, { isLoading: true, error: null });
      try {
        const req: APICreateJobRequest = {
          repo_url: store.formData.repo_url() || undefined,
          repo_path: store.formData.repo_path() || undefined,
          analysis_scope: store.formData.analysis_scope(),
          budget_config: {
            max_tokens: store.formData.max_tokens(),
            max_cost_usd: store.formData.max_cost_usd()
          }
        };
        const job = await jobsService.createJob(req).toPromise();
        if (job) {
          router.navigate(['/jobs', job.id]);
        }
      } catch (err: any) {
        patchState(store, { error: err.error?.message || 'Failed to trigger analysis job.', isLoading: false });
      }
    }
  }))
);

